//! End-to-end tests over MOD0 modules linked by LLD (generated by tools/python/modules.py).
use std::{
    fs,
    path::{Path, PathBuf},
    process::Command,
    sync::atomic::{AtomicU64, Ordering},
};
static ID: AtomicU64 = AtomicU64::new(0);
struct Temp(PathBuf);
impl Temp {
    fn new() -> Self {
        let p = std::env::temp_dir().join(format!(
            "wanderlust-modules-{}-{}",
            std::process::id(),
            ID.fetch_add(1, Ordering::Relaxed)
        ));
        fs::create_dir(&p).unwrap();
        Self(p)
    }
}
impl Drop for Temp {
    fn drop(&mut self) {
        let _ = fs::remove_dir_all(&self.0);
    }
}
fn cli() -> Command {
    Command::new(env!("CARGO_BIN_EXE_wanderlust"))
}
fn python() -> String {
    if let Ok(p) = std::env::var("WL_PYTHON") {
        return p;
    }
    for candidate in ["python3", "python"] {
        if Command::new(candidate)
            .arg("--version")
            .output()
            .is_ok_and(|o| o.status.success())
        {
            return candidate.into();
        }
    }
    panic!("Python 3 is required to generate LLD-linked module fixtures (set WL_PYTHON)");
}
/// Generates both relocation formats and returns the fixture directory.
fn fixtures(t: &Temp) -> PathBuf {
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
    let out = t.0.join("modules");
    let o = Command::new(python())
        .arg(root.join("tools/python/modules.py"))
        .arg("--out-dir")
        .arg(&out)
        .output()
        .unwrap();
    assert!(o.status.success(), "{}", String::from_utf8_lossy(&o.stderr));
    out
}
fn json(o: &std::process::Output) -> serde_json::Value {
    assert!(o.status.success(), "{}", String::from_utf8_lossy(&o.stderr));
    serde_json::from_slice(&o.stdout).unwrap()
}
fn manifest(dir: &Path) -> serde_json::Value {
    serde_json::from_slice(&fs::read(dir.join("manifest.json")).unwrap()).unwrap()
}

#[test]
fn lld_linked_modules_relocate_and_execute_natively() {
    let t = Temp::new();
    let dir = fixtures(&t);
    for variant in ["rela", "rel"] {
        let input = dir.join(variant);
        let expected = manifest(&input);
        let process = json(&cli().arg("link").arg(&input).output().unwrap());
        assert_eq!(process["execution_blocker"], serde_json::Value::Null);
        assert_eq!(process["link"]["unresolved_symbols"], 0);
        assert!(
            process["link"]["diagnostics"]
                .as_array()
                .unwrap()
                .is_empty()
        );
        let base = |name: &str| {
            process["modules"]
                .as_array()
                .unwrap()
                .iter()
                .find(|m| m["name"] == name)
                .unwrap()["base"]
                .as_u64()
                .unwrap()
        };
        let symbol = |module: &str, name: &str| {
            expected["modules"][module]["symbols"][name]
                .as_u64()
                .unwrap()
        };
        // Every code pointer produced by relocation must be a symbol address computed by LLD.
        let pointers: Vec<u64> = process["code_pointers"]
            .as_array()
            .unwrap()
            .iter()
            .filter(|c| c["source"] == "relocation")
            .map(|c| c["address"].as_u64().unwrap())
            .collect();
        let mut wanted = vec![
            base("main") + symbol("main", "local_triple"),
            base("main") + symbol("main", "local_inc"),
            base("sdk") + symbol("sdk", "sdk_add_bias"),
            base("sdk") + symbol("sdk", "sdk_double"),
        ];
        wanted.sort();
        assert_eq!(pointers, wanted, "{variant}");
        let exe =
            t.0.join(format!("{variant}{}", std::env::consts::EXE_SUFFIX));
        let built = json(
            &cli()
                .arg("recompile")
                .arg(&input)
                .arg("--out")
                .arg(&exe)
                .output()
                .unwrap(),
        );
        assert_eq!(built["relocation"], "applied-by-host");
        let run = Command::new(&exe).output().unwrap();
        let state = json(&run);
        assert_eq!(state["status"], "returned");
        assert_eq!(state["x"][0], expected["expected_x0"], "{variant}");
        assert_eq!(
            state["x"][9], 1001,
            "sdk_counter incremented through the GOT"
        );
        assert_eq!(state["steps"], 43);
    }
}
#[test]
fn unrelocated_execution_is_refused_or_faults() {
    let t = Temp::new();
    let dir = fixtures(&t).join("rela");
    // A single MOD0 file with relocations cannot be compiled without the loader.
    let o = cli()
        .arg("recompile")
        .arg(dir.join("main"))
        .args(["--entry", "0x10000", "--out"])
        .arg(t.0.join("single"))
        .output()
        .unwrap();
    assert!(!o.status.success());
    assert!(String::from_utf8_lossy(&o.stderr).contains("not applied"));
    // Guest linking without rtld maps the image unrelocated: the PLT slot still holds a
    // module-relative stub address, so the import call faults instead of being guessed.
    let linked = json(
        &cli()
            .arg("link")
            .arg(&dir)
            .args(["--link", "guest"])
            .output()
            .unwrap(),
    );
    assert_eq!(
        linked["link"]["diagnostics"][0]["kind"],
        "guest-linker-required"
    );
    let exe = t.0.join(format!("guest{}", std::env::consts::EXE_SUFFIX));
    json(
        &cli()
            .arg("recompile")
            .arg(&dir)
            .args(["--link", "guest", "--out"])
            .arg(&exe)
            .output()
            .unwrap(),
    );
    let run = Command::new(&exe).output().unwrap();
    assert_eq!(run.status.code(), Some(1));
    let state: serde_json::Value = serde_json::from_slice(&run.stdout).unwrap();
    assert_eq!(state["status"], "fault");
    assert!(
        state["pc"].as_u64().unwrap() < 0x8000000,
        "branched to an unrelocated address"
    );
}
#[test]
fn inspect_reports_dynamic_metadata() {
    let t = Temp::new();
    let dir = fixtures(&t).join("rela");
    let v = json(
        &cli()
            .arg("inspect")
            .arg(dir.join("main"))
            .arg("--json")
            .output()
            .unwrap(),
    );
    let d = &v["dynamic_summary"];
    assert_eq!(d["needed"][0], "sdk");
    assert_eq!(d["rela_count"], 2);
    assert_eq!(d["relocations"]["R_AARCH64_RELATIVE"], 2);
    assert_eq!(d["relocations"]["R_AARCH64_JUMP_SLOT"], 1);
    assert_eq!(d["pltrel"], "PltRela");
    assert_eq!(v["module_id"].as_str().unwrap().len(), 64);
}
#[test]
fn unsupported_instruction_becomes_precise_runtime_fault() {
    let t = Temp::new();
    // CBZ X0 skips the unsupported word (URECPE V0.4S, V1.4S: integer estimates are not implemented).
    let words: Vec<u8> = [0xb4000040u32, 0x4ea1c820, 0xd65f03c0]
        .iter()
        .flat_map(|w| w.to_le_bytes())
        .collect();
    let input = t.0.join("guest.a64");
    fs::write(&input, words).unwrap();
    let strict = cli()
        .arg("recompile")
        .arg(&input)
        .args(["--raw", "--entry", "0x10000", "--emit-only", "--out"])
        .arg(t.0.join("strict"))
        .output()
        .unwrap();
    assert!(!strict.status.success());
    let exe = t.0.join(format!("lenient{}", std::env::consts::EXE_SUFFIX));
    let built = json(
        &cli()
            .arg("recompile")
            .arg(&input)
            .args([
                "--raw",
                "--entry",
                "0x10000",
                "--allow-unsupported",
                "--out",
            ])
            .arg(&exe)
            .output()
            .unwrap(),
    );
    assert_eq!(built["unsupported_sites"], 1);
    assert_eq!(json(&Command::new(&exe).output().unwrap())["x"][0], 0);
    let o = Command::new(&exe).args(["--reg", "0=3"]).output().unwrap();
    assert_eq!(o.status.code(), Some(1));
    let stderr = String::from_utf8_lossy(&o.stderr);
    assert!(
        stderr.contains("0x4ea1c820") && stderr.contains("0x10004"),
        "{stderr}"
    );
}
#[test]
fn traps_and_alignment_faults_are_reported() {
    let t = Temp::new();
    for (name, words, args, message) in [
        ("brk", vec![0xd2800020u32, 0xd4200020], vec![], "BRK #0x1"),
        // LDXR X5, [X2] with X2 = 0x10000004: exclusive accesses require natural alignment.
        (
            "ldxr",
            vec![0xc85f7c45, 0xd65f03c0],
            vec!["--reg", "2=0x10000004"],
            "alignment fault",
        ),
    ] {
        let input = t.0.join(format!("{name}.a64"));
        fs::write(
            &input,
            words
                .iter()
                .flat_map(|w| w.to_le_bytes())
                .collect::<Vec<_>>(),
        )
        .unwrap();
        let exe = t.0.join(format!("{name}{}", std::env::consts::EXE_SUFFIX));
        json(
            &cli()
                .arg("recompile")
                .arg(&input)
                .args(["--raw", "--entry", "0x10000", "--out"])
                .arg(&exe)
                .output()
                .unwrap(),
        );
        let o = Command::new(&exe).args(args).output().unwrap();
        assert_eq!(o.status.code(), Some(1));
        assert!(
            String::from_utf8_lossy(&o.stderr).contains(message),
            "{}",
            String::from_utf8_lossy(&o.stderr)
        );
    }
}

/// A raw program whose blocks span several 256-byte translation units: a loop calls a
/// function three windows away directly and a second one through BLR.
fn cross_unit_program() -> Vec<u8> {
    let nop = 0xd503201fu32;
    let mut w = vec![nop; 0x300 / 4];
    let at = |a: usize| a / 4;
    let b_to = |from: usize, to: usize, link: bool| {
        (if link { 0x94000000u32 } else { 0x14000000 })
            | (((to as i64 - from as i64) / 4) as u32 & 0x3ff_ffff)
    };
    // 0x000: mov x19, x30; mov x0, #0; mov x1, #50; adr x20, f2
    w[0] = 0xaa1e03f3;
    w[1] = 0xd2800000;
    w[2] = 0xd2800641;
    // adr x20, 0x2c0 (immlo in bits 30:29, immhi in bits 23:5)
    let delta = 0x2c0u32 - 0x0c;
    w[3] = 0x10000000 | ((delta & 3) << 29) | ((delta >> 2) << 5) | 20;
    // 0x010 loop: bl f1 (0x140); blr x20; subs x1, x1, #1; b.ne loop
    w[at(0x10)] = b_to(0x10, 0x140, true);
    w[at(0x14)] = 0xd63f0280;
    w[at(0x18)] = 0xf1000421;
    w[at(0x1c)] = 0x54000001 | ((((0x10i64 - 0x1c) / 4) as u32 & 0x7ffff) << 5);
    // mov x30, x19; ret
    w[at(0x20)] = 0xaa1303fe;
    w[at(0x24)] = 0xd65f03c0;
    // 0x140 f1: add x0, x0, x1; ret   (another unit)
    w[at(0x140)] = 0x8b010000;
    w[at(0x144)] = 0xd65f03c0;
    // 0x2c0 f2: add x0, x0, #3; ret   (a third unit)
    w[at(0x2c0)] = 0x91000c00;
    w[at(0x2c4)] = 0xd65f03c0;
    w.iter().flat_map(|x| x.to_le_bytes()).collect()
}
fn build_raw(t: &Temp, input: &Path, name: &str, extra: &[&str]) -> (PathBuf, serde_json::Value) {
    let exe = t.0.join(format!("{name}{}", std::env::consts::EXE_SUFFIX));
    let report = json(
        &cli()
            .arg("recompile")
            .arg(input)
            .args(["--raw", "--entry", "0x10000", "--seed", "0x102c0", "--out"])
            .arg(&exe)
            .args(extra)
            .output()
            .unwrap(),
    );
    (exe, report)
}
#[test]
fn execution_across_translation_units_matches_single_unit() {
    let t = Temp::new();
    let input = t.0.join("cross.a64");
    fs::write(&input, cross_unit_program()).unwrap();
    // sum_{k=1..50} k + 3 * 50 = 1275 + 150.
    for (name, shift) in [("split", "8"), ("whole", "20")] {
        let (exe, report) = build_raw(&t, &input, name, &["--unit-shift", shift]);
        assert_eq!(report["units"], if shift == "8" { 3 } else { 1 });
        let state = json(&Command::new(exe).output().unwrap());
        assert_eq!(state["x"][0], 1425, "{name}");
        assert_eq!(state["steps"], 4 + 50 * 8 + 2, "{name}");
    }
    // The relocated two-module fixture with one unit per 256-byte window.
    let dir = fixtures(&t).join("rela");
    let exe =
        t.0.join(format!("small-units{}", std::env::consts::EXE_SUFFIX));
    json(
        &cli()
            .arg("recompile")
            .arg(&dir)
            .args(["--unit-shift", "8", "--out"])
            .arg(&exe)
            .output()
            .unwrap(),
    );
    let state = json(&Command::new(&exe).output().unwrap());
    assert_eq!(
        (state["x"][0].as_u64(), state["x"][9].as_u64()),
        (Some(1681), Some(1001))
    );
}
#[test]
fn build_cache_reuses_unchanged_units() {
    let t = Temp::new();
    let input = t.0.join("cross.a64");
    let program = cross_unit_program();
    fs::write(&input, &program).unwrap();
    let cache = t.0.join("cache");
    let args = ["--unit-shift", "8", "--cache-dir", cache.to_str().unwrap()];
    let (_, cold) = build_raw(&t, &input, "cold", &args);
    assert_eq!(
        (
            cold["build"]["cache_hits"].as_u64(),
            cold["build"]["cache_misses"].as_u64()
        ),
        (Some(0), Some(4))
    );
    let (_, warm) = build_raw(&t, &input, "warm", &args);
    assert_eq!(
        (
            warm["build"]["cache_hits"].as_u64(),
            warm["build"]["cache_misses"].as_u64()
        ),
        (Some(4), Some(0))
    );
    // Change f2's immediate: only the unit holding 0x102c0 is recompiled.
    let mut changed = program;
    changed[0x2c0..0x2c4].copy_from_slice(&0x91001c00u32.to_le_bytes()); // add x0, x0, #7
    fs::write(&input, &changed).unwrap();
    let (exe, edited) = build_raw(&t, &input, "edited", &args);
    assert_eq!(
        (
            edited["build"]["cache_hits"].as_u64(),
            edited["build"]["cache_misses"].as_u64()
        ),
        (Some(3), Some(1))
    );
    assert_eq!(
        json(&Command::new(exe).output().unwrap())["x"][0],
        1275 + 350
    );
}
#[test]
fn llvm_compiled_simd_kernel_matches_host_oracle() {
    let target_lib = Command::new("rustc")
        .args([
            "--print",
            "target-libdir",
            "--target",
            "aarch64-unknown-none",
        ])
        .output()
        .unwrap();
    let lib = PathBuf::from(String::from_utf8_lossy(&target_lib.stdout).trim());
    if !lib.join("..").join("lib").is_dir()
        || !fs::read_dir(&lib).is_ok_and(|mut d| d.next().is_some())
    {
        eprintln!("skipped: the aarch64-unknown-none Rust target is not installed");
        return;
    }
    let t = Temp::new();
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
    let guest = t.0.join("kernel");
    let o = Command::new(python())
        .arg(root.join("tools/python/modules.py"))
        .args(["--rust"])
        .arg(root.join("tests/programs/guest.rs"))
        .arg("--out-dir")
        .arg(&guest)
        .output()
        .unwrap();
    assert!(o.status.success(), "{}", String::from_utf8_lossy(&o.stderr));
    let host = t.0.join(format!("host{}", std::env::consts::EXE_SUFFIX));
    let o = Command::new("rustc")
        .args(["--edition", "2024", "-C", "opt-level=3"])
        .arg(root.join("tests/programs/host.rs"))
        .arg("-o")
        .arg(&host)
        .output()
        .unwrap();
    assert!(o.status.success(), "{}", String::from_utf8_lossy(&o.stderr));
    let exe = t.0.join(format!("guest{}", std::env::consts::EXE_SUFFIX));
    let built = json(
        &cli()
            .arg("recompile")
            .arg(&guest)
            .arg("--out")
            .arg(&exe)
            .output()
            .unwrap(),
    );
    assert_eq!(built["unsupported_sites"], 0);
    for seed in ["0x123456789abcdef", "0xfeedface00c0ffee"] {
        let expected = Command::new(&host).arg(seed).output().unwrap();
        let expected = String::from_utf8_lossy(&expected.stdout);
        let expected: u64 = expected.split_whitespace().nth(1).unwrap().parse().unwrap();
        let state = json(
            &Command::new(&exe)
                .args(["--reg", &format!("0={seed}"), "--steps", "100000000"])
                .output()
                .unwrap(),
        );
        assert_eq!(state["status"], "returned");
        assert_eq!(state["x"][0].as_u64(), Some(expected), "seed {seed}");
    }
}
